import sys

def main():
    lines = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(lines):
        n = int(lines[idx])
        idx += 1
        if n == 0:
            break
        perm = [int(lines[idx + i]) for i in range(n)]
        idx += n

        inv = [0] * n
        for i in range(n):
            val = perm[i]
            inv[val - 1] = i + 1

        if perm == inv:
            out.append("ambiguous")
        else:
            out.append("not ambiguous")

    for line in out:
        print(line)

if __name__ == "__main__":
    main()
